     "text": "Kathy Weber grenzt Abenteuer von Spiel und Spaß ab und ordnet es in ihrem Konzept Lila Liebe als Unterbedürfnis von Sicherheit ein. Nicht jeder sei der klassische Abenteurertyp, und man solle nicht bewerten, welche Art besser ist. Sie vergleicht ihr Kind, das Grenzen und Nervenkitzel sucht, mit ihrer achtjährigen Tochter, die bei Gruseligem in Panik gerät und trotzdem wachsen will. Ängstliche Kinder brauchen aus ihrer Sicht viel Orientierung und danach Mamanähe, um den Tank zu füllen. Eigene Erfahrungen sollen Eltern nicht auf das Kind übertragen. Ein Kind, das Nein sagen darf, lerne, für sich einzustehen."
