    "Wenn Festhalten nötig ist, kündigt es an und lobt das Kind danach, denn viele Kinder sind hinterher stolz.",
    "Sprecht vorher mit der Ärztin ab, wie es ablaufen soll, etwa dass das Kind zuerst direkt angesprochen wird, und sagt Stopp, wenn sich die Praxis nicht daran hält.",
    "Erklärt Impfungen über die Fantasie des Kindes, etwa mit Ninjas, die eine Festung im Körper bauen, und schaut gemeinsam Bücher zum Arztbesuch an.",
    "Legt euch für Medizin, die das Kind nicht nehmen will, Pläne zurecht: erst eine Geschichte (zum Beispiel Zaubertrank oder Einhörner, bei der das Kind mitentscheiden darf), dann Mischen mit etwas Süßem oder eine kleine Belohnung und zuletzt die Frage beim Arzt nach einem anderen Präparat.",
    "Übt die Blutabnahme vorher mit einem Kugelschreiber am Kuscheltier und am Arm des Kindes, erklärt, dass der Arm locker bleiben soll, und fragt bei Panik die Ärztin nach Alternativen wie einem Betäubungsspray."
