     "text": "Die Hosts sehen Wertschätzung für Gegenstände als wichtigen Aspekt des Aufräumens. Dinge, die Kindern wirklich wichtig sind, würden meist gepflegt und aufgeräumt, und wer bei jedem Defekt sofort Ersatz kauft, vermittle wenig Wert. Wenn Kinder merken, dass ihnen nicht alles fehlt, was nicht mehr da ist, falle ihnen das Loslassen leichter. Die Wichtelchen-Idee stammt laut den Hosts aus einem Buch. Sie betonen, dass sie keine Drohung sein darf und bei manchen Kindern Druck oder Angst auslösen kann; es müsse bei jedem Kind ausprobiert werden. Als Erfahrung berichten sie, dass Kinder beim Anblick der Kiste überlegen, ob sie etwas noch wollen, und manches freiwillig weggeben."
