    "Wenn ihr allein mit dem Baby seid, könnt ihr einen Schlaf in der Trage machen und euch zu einem anderen Schlaf mit hinlegen.",
    "Das Baby auf dem Rücken zu tragen kann gut funktionieren, um nebenbei etwas im Haushalt zu erledigen.",
    "Entscheidet danach, was für eure Familie am besten ist, nicht nach dem, was im Internet gesagt wird.",
