    "Wenn das Baby weint, haltet es nach Möglichkeit im Arm, denn laut Nicola Schmidt ist Weinen am Körper weniger stressig als allein. Wenn ihr selbst am Ende seid, legt das Baby sicher ab und holt Hilfe.",
