   "kurz": "Die mutti-Hosts erziehen nicht mehr bedürfnisorientiert und erleben diesen Ansatz vor allem als erschöpfend und in der Praxis oft zu permissiv. Nicola Schmidt und Kathy Weber (gfk) halten dagegen daran fest, betonen aber beide, dass Bedürfnisse anerkennen nicht heißt, sie immer sofort zu erfüllen, und dass Eltern Orientierung und Führung geben müssen. Uneinig sind die Podcasts darin, ob die Methode selbst das Problem ist oder ihr verbreitetes Missverständnis.",
   "tipps": [
    "Fragt euch bei störendem Verhalten, welche Fähigkeit eurem Kind noch fehlt und wie ihr sie ihm beibringen könnt, statt nur nach dem Bedürfnis dahinter zu suchen.",
    "Gebt unerwünschtem Verhalten wenig Energie, lenkt in ein Spiel oder eine andere Tätigkeit um und ignoriert dabei das Kind selbst nicht und tragt nichts nach.",
    "Sagt klar, was jetzt passiert, und handelt (aufstehen und losgehen), statt mehrfach anzukündigen und zu verhandeln; nonverbale Signale wie Kopfschütteln oder eine Hand auf der Schulter helfen, und Dinge erklärt ihr einmal ruhig.",
    "Unterscheidet Wunsch und Bedürfnis, denn Essen ist ein Bedürfnis, ein bestimmtes Gericht oder das dritte Eis nicht, und ihr müsst nicht für jedes Kind extra kochen.",
    "Bei kleinen Anlässen dürft ihr sagen, dass es kein Grund zum Ausrasten ist, und eine Lösung anbieten, etwa den Pullover wechseln; zeigt dabei ehrlich, wenn ihr ärgerlich seid, statt Ratgebersätze ruhig abzuspulen.",
    "Prüft bei einem Wunsch, ob es ein spontaner Impuls ist, dessen Folgen euer Kleinkind nicht absehen kann; dann gebt Orientierung. Bei harmlosen Wünschen bietet Wahlmöglichkeiten an.",
    "Erkennt das Bedürfnis an und sagt trotzdem Nein, ohne das Kind zu beschämen, etwa mit Sätzen wie, es sei doch schon groß.",
    "Fragt kleine Kinder nicht hilflos, was sie brauchen, denn das überfordert sie; beobachtet stattdessen, was sie tun, und übersetzt es in ein mögliches Bedürfnis (Kathy Weber, gfk).",
    "Behaltet alle Bedürfnisse im Blick, auch eure eigenen: Sie werden bestmöglich, aber nicht immer sofort erfüllt, und oft hilft schon, dass das Kind sich wahrgenommen fühlt, damit es warten mag (Kathy Weber, gfk)."
   ],
   "sichtweisen": [
    {
     "podcast": "mutti",
     "text": "Die Hosts erziehen nach eigener Aussage nicht mehr bedürfnisorientiert und kritisieren die Szene deutlich: Sie halte Kinder für unschuldig, erkläre schwieriges Verhalten vorschnell mit Gefühlsstärke oder Neurodivergenz und münde in der Praxis oft in permissive Erziehung. Sie weisen zurück, es nur falsch umgesetzt zu haben. Laut den Hosts gibt es nach der Selbstbestimmungstheorie nur drei belegte Grundbedürfnisse (Autonomie, soziale Eingebundenheit, Kompetenz); Liebe allein reiche nicht, Fähigkeiten müssten aktiv vermittelt werden. Gefühle begleiten sei eine Empfehlung für Fachkräfte in Kita und Schule, nicht für den Familienalltag, und manche Kinder würden vom ständigen Spiegeln noch wütender. Sie sehen sich heute als Bergführer mit natürlicher Autorität und berichten, dass der Alltag innerhalb weniger Monate ruhiger wurde. Uneinig sind sie in einem Punkt: Ein Host hält es für denkbar, dass optimal umgesetzte bedürfnisorientierte Erziehung in der Theorie funktioniert, der andere glaubt das nicht. Die Attachment-Parenting-Ideen (die sieben Baby-Bs) halten sie grundsätzlich für gut, kritisieren aber den dogmatischen Anspruch und den Druck auf Mütter. Dass Stillen für die Bindung wichtig sei, sei laut den Hosts nicht belegt."
    },
    {
     "podcast": "artgerecht",
     "text": "Nicola Schmidt sieht Bedürfnisorientierung als Kern ihres Ansatzes und grenzt sich zugleich vom reinen Nachgeben ab. Bedürfnisse anzuerkennen heiße nicht, sie immer zu erfüllen: Eltern dürfen Nein sagen, ohne das Kind zu beschämen. Laut ihr entwickeln Kinder, deren Bedürfnisse mitfühlend beantwortet werden, mehr Selbstkontrolle. Kleinkinder können die Folgen ihrer spontanen Wünsche nicht absehen, deshalb müssten Eltern als Menschen mit Erfahrung Orientierung geben. Mit den mutti-Hosts trifft sie sich in der Forderung nach Führung und in der Unterscheidung von Wunsch und Bedürfnis. Sie widerspricht ihnen aber darin, dass der Ansatz selbst das Problem sei: Für sie ist feinfühliges Reagieren gerade der Weg, nicht permissive Erziehung."
    },
    {
     "podcast": "gfk",
     "text": "Kathy Weber nennt es das größte Missverständnis, bedürfnisorientierte Elternschaft heiße, nur die Bedürfnisse der Kinder sofort und immer zu erfüllen; nach ihrer Erfahrung werden Kinder dann zu Tyrannen und Eltern zu Zombies. Gemeint seien alle Bedürfnisse in der Familie, auch die der Eltern, bestmöglich erfüllt, aber nicht sofort. Sie sieht den Ansatz weder als autoritär noch als antiautoritär, sondern als Mitte aus Empathie und Führung. Wie die mutti-Hosts und Nicola Schmidt trennt sie Bedürfnisse (für alle Menschen gleich, nicht verhandelbar) von Wünschen, die nur mögliche Strategien sind. Anders als mutti verteidigt sie den Ansatz selbst und sieht das Problem im Missverständnis; sie verzichtet zudem auf Belohnung, Strafe und ein globales Richtig und Falsch, will Kindern aber Orientierung über die Werte der Eltern und das Warum geben. Ein zwölfjähriger Sohn erzählt in einer Folge, ihn nerve nicht die GfK, sondern zu viel Reden und Gefühlsanalyse."
    }
   ],
