   "bereiche": [
    "eltern",
    "alltag"
   ],
   "kurz": "Ob Eltern ein Team sind, entscheidet vor allem die Haltung: Beide fühlen sich verantwortlich und blicken wohlwollend auf den anderen. Wichtiger als eine 50-50-Aufteilung ist, dass nicht einer die Verantwortung trägt, während der andere nur hilft. Alle drei Podcasts raten, bei Ärger zuerst bei sich selbst zu schauen und dann ruhig zu sprechen, statt den Partner zu belehren. Kathy Weber (gfk) ergänzt, dass jeder seinen eigenen Weg gehen darf und der Partner Nein sagen kann, außer wenn ein Kind geschützt werden muss.",
   "tipps": [
    "Klärt pro Situation, wer verantwortlich ist, zum Beispiel einer macht die Küche und der andere bringt die Kinder ins Bett, und lasst den anderen machen, ohne bei jeder Abweichung einzuspringen.",
    "Greift nur ein, wenn es eskaliert, etwa wenn der andere das Kind anschreit oder selbst weint, und sagt dann klar „Stopp, ich übernehme“. Sonst fragt vorher, ob er Unterstützung möchte, und vereinbart ein Codewort für den Wechsel, das auch für ihn passt.",
    "Atmet aus und spürt nach, welches Gefühl aufkommt, bevor ihr den anderen unterbrecht oder korrigiert. Fragt euch auch, ob der andere gegen euch gehandelt hat oder gerade für die Familie etwas anderes getan hat.",
    "Sprecht Kritik später und ohne Kind an, in Ich-Form und mit Was- und Wie-Fragen statt Warum-Fragen. Fragt vorher, ob der andere etwas hören möchte, und nehmt ein Nein an.",
    "Tauscht Perspektiven ohne Ergebnisdruck aus: Schreibt jeweils auf, was euch in der Erziehung wichtig ist, hört einander zu und besprecht Rollen und Entscheidungen später noch einmal. Begrenzte Gesprächszeiten mit nur einem Thema pro Abend können helfen.",
    "Bedenkt, dass meist die Person, die die meiste Zeit mit den Kindern verbringt, die Regeln prägt. Einigt euch nur auf Dinge, die ihr auch umsetzen könnt und hinter denen ihr steht.",
    "Gebt dem Partner Zeit zu lernen, wenn er bisher weniger gemacht hat, und lasst Fehler zu, weil ihr am Anfang selbst welche gemacht habt. Wechselt euch bei den Nächten mit dem Kind ab, wenn jemand getrennt schlafen möchte.",
    "Gönnt dem heimkommenden Partner kurz Zeit zum Ankommen und schafft danach auch dem Elternteil eine Pause, der zu Hause war.",
    "Ladet den Partner ein, statt ihn zu überzeugen: Lebt euren Weg vor, legt Podcast-Folgen oder Bücher einfach hin und erwartet nicht, dass er mitmacht. Kümmert euch selbst um das Bedürfnis hinter eurem Wunsch (zum Beispiel Verbindung oder Austausch)."
   ],
   "sichtweisen": [
    {
     "podcast": "mutti",
     "text": "Die Hosts sind sich in diesem Thema weitgehend einig. Sie sagen, es hänge zu über 80 Prozent an der Haltung, ob Eltern ein Team sind, und die Aufgaben dürften nach Stärken und Zeit verteilt werden. Sie kritisieren, wenn feministische Begriffe unreflektiert auf die eigene Partnerschaft übertragen werden, betonen aber zugleich, dass Feminismus wichtig ist und Väter Verantwortung aktiv übernehmen sollen. Weaponized Incompetence, also absichtlich schlecht gemachte Aufgaben, halten sie in den meisten Partnerschaften für selten; meist mache der Elternteil mit weniger Übung einfach mehr Fehler. Maternal Gatekeeping, wenn die Mutter dem Vater ständig reinredet, ist nach ihrer Darstellung dagegen real, und die Klage der Väter darüber teils berechtigt. Mit Verweis auf das Salienz-Netzwerk erklären die Hosts, dass das Gehirn filtert, was wahrgenommen wird, je nachdem, wofür man sich zuständig fühlt. Daher höre ein Vater, der sich nicht zuständig fühlt, nächtliches Schreien oft nicht. Auch Erwerbsarbeit und Care-Arbeit sollte man nicht gegeneinander aufwiegen; kritisch sieht eine Host, wenn Männer selbstverständlich getrennt schlafen, während die Mutter nachts beim Kind ist."
    },
    {
     "podcast": "artgerecht",
     "text": "Nicola Schmidt behandelt das Thema über unterschiedliche Erziehungsvorstellungen. Sie lehnt ab, den Partner auf den richtigen Weg bringen zu wollen: Jeder gehe seinen eigenen Weg. Der erste Schritt ist für sie Selbstfürsorge, also wahrnehmen, was der Anblick in euch auslöst, ausatmen und das Gefühl aushalten. Wut sei oft sekundär, dahinter stünden häufig Traurigkeit oder Angst. Danach rät sie zu einem Gespräch, in dem jeder nur über sich spricht und zunächst nichts entschieden werden muss. Mit mutti stimmt sie überein bei Ich-Form, ruhigem Ton und der Idee, dass im Alltag vor allem die Person Regeln setzt, die die Zeit mit den Kindern verbringt. Sie sagt aber deutlicher, dass man den anderen nicht zum Erfüllungsgehilfen der eigenen Erziehung machen kann und wer wenig Zeit mit den Kindern hat, weniger Einfluss hat. Die Heckners betonen stärker, dass Väter aktiv Verantwortung übernehmen sollen, und benennen Mechanismen wie Maternal Gatekeeping."
    },
    {
     "podcast": "gfk",
     "text": "Kathy Weber sagt, dass fast alle Eltern Erziehungsunterschiede haben und nicht einer Meinung sein müssen: Jeder darf sein eigenes Richtig haben, und neben dem eigenen Weg gibt es einen gemeinsamen als Elternteam. Wünsche an den Partner (er soll Gespräche führen oder Tipps annehmen) seien keine Bedürfnisse; das Bedürfnis dahinter erfülle man sich unabhängig von ihm. Der Partner dürfe Nein sagen, und je mehr er das darf, desto eher sage er irgendwann Ja. Solange keine Grenze überschritten wird, ist laut ihr der Elternteil zuständig, der gerade beim Kind ist; bei einer krassen Grenzüberschreitung gehe man ohne Rückfrage dazwischen, aber als Schutzschild für die Kinder und nicht gegen den Partner. Sie lehnt Belehren und ständiges Korrigieren ab und rät, zuerst zu fragen, ob der Partner eine Rückmeldung hören will. Mit artgerecht teilt sie Selbstfürsorge zuerst und Ich-Form; Fragen wie Aufgabenverteilung, Care-Arbeit oder Maternal Gatekeeping, die bei mutti breit vorkommen, behandeln die gfk-Notizen kaum. Auch Harmonie ohne Konflikte sieht sie kritisch: Konflikte dürfen sein, wichtig sei die Verbindung."
    }
   ],
