   "kurz": "Elternsein ist ein Marathon: Wer dauerhaft über seinen Kräften lebt, steuert auf einen Zusammenbruch zu. Beide Podcasts raten deshalb, für sich zu sorgen (Schlaf, Essen, Pausen), den Alltag und die Termine zu vereinfachen und Grenzen ehrlich anzusagen. In einer akuten Krise reicht „ausreichend“, nichts muss perfekt sein.",
   "tipps": [
    "Geht bewusst früh ins Bett und macht dort etwas Ruhiges wie Lesen oder Stricken, statt abends noch Serien zu schauen oder Nachrichten zu lesen, denn Schlaf hat Vorrang vor Haushalt. Sorgt außerdem dafür, dass ihr selbst genug esst, und plant schnelle Mahlzeiten oder Snacks ein, statt Hunger aufzuschieben.",
    "Plant schon tagsüber Pausen für euch ein, damit der Abend nicht der Moment ist, an dem ihr erst durchatmen wollt. Nach Nicola Schmidt hilft auch, sich einmal am Tag fünf Minuten hinzulegen. Plant euren Alltag außerdem so, dass höchstens etwa 70 Prozent eurer Kraft draufgehen, damit für schwierige Phasen Luft bleibt.",
    "Macht einmal am Tag einen kurzen Bedürfnis-Check: Welches Bedürfnis ist heute am wichtigsten, und welche kleine Strategie passt in den Alltag? Schon 30 Sekunden bis eine Minute zählen, und wenn eine Strategie nicht klappt, sucht neugierig eine andere.",
    "Wenn ein belastender Gedanke immer wiederkommt („Ich schaffe es nicht“, „Ich bin eine schlechte Mutter“), verurteilt ihn nicht, sondern übersetzt ihn: Welche ein bis drei Gefühle stecken dahinter, und welches unerfüllte Bedürfnis zeigt sich?",
    "Sprecht offen mit eurem Partner darüber, wie schlecht es euch geht, und plant gemeinsam, wann und wie ihr entlastet werdet.",
    "Vereinfacht den Haushalt, indem ihr Wäsche nicht faltet, sondern in Kartons sortiert, Spielzeug abends mit dem Besen in eine große Kiste kehrt und einfach kocht, etwa Nudeln mit Käse oder Butterbrot.",
    "Sagt zu Terminen öfter Nein und sagt anderen ehrlich, was ihr gerade nicht schafft, auch euren Kindern, etwa dass ihr heute nicht spielen wollt oder nur in den Wald geht statt zum Schwimmen.",
    "Nehmt, wenn möglich, Kita, Tagespflege, Babysitter, Haushaltshilfe oder einen festen Treff mit anderen Eltern ohne schlechtes Gewissen in Anspruch, und holt professionelle Hilfe, wenn es euch nicht gut geht.",
    "Wenn Gedanken kreisen, schreibt auf, wie ihr euch fühlt und wo im Körper ihr es spürt, und holt euch mit einem Reiz raus, etwa Wasser am offenen Fenster trinken, etwas essen oder rausgehen."
   ],
   "sichtweisen": [
    {
     "podcast": "mutti",
     "text": "Die Hosts sind in diesem Thema entlastend und pragmatisch. Sie vergleichen das Elternleben mit einem Marathon: Die ersten ein bis zwei Jahre mit Baby seien die Trainingsphase, in der man seine Belastbarkeit erst aufbaut. Wer sich mit Eltern vergleicht, die schon lange dabei sind, vergleiche sich mit trainierten Läufern. Viele Erstlingseltern gäben 200 Prozent und rutschten ins Intensive Parenting. Eine Host berichtet, dass sie selbst so im Burnout gelandet ist. Schlaf und Essen halten sie für die größten Hebel. Eine Mutter, die nur fürs Kind lebt, habe ihr Leben nicht im Griff, und das schade auch dem Kind. Sie kritisieren den Druck aus sozialen Medien, das Kind ständig zu fördern, und wollen ideologische Vorbehalte gegen die Kita über Bord werfen, wenn es der Mutter schlecht geht. Beim Fernsehen als Entlastung sind sie nicht einig: Eine Host-Familie wurde davon überreizt, eine Host erlaubt am Sonntag einen Film, die andere setzt auf frühes Aufstehen. Sie weisen außerdem darauf hin, dass Therapie- und Kurplätze schwer zu bekommen sind."
    },
    {
     "podcast": "artgerecht",
     "text": "Nicola Schmidt spricht aus eigener Erfahrung und sieht die Erschöpfung eher im überfüllten Tagesplan der Eltern als im Kind. Sie rät, schon tagsüber mehr Pausen einzubauen und öfter Nein zu Terminen zu sagen. Eltern aus ihren Camps hätten berichtet, dass es mit viel weniger Terminen genauso schön war. Außerdem beschreibt sie, dass man sich ständig verbiegt, wenn man es allen recht machen will, und dass Selbstfürsorge auch Fürsorge für andere ist. Mit den mutti-Hosts stimmt sie darin überein, dass Schlaf, Selbstversorgung und ein vereinfachter Alltag zentral sind und dass man offen ansagen darf, was gerade nicht geht. Sie ergänzt konkrete Mittel wie Körperwahrnehmung aufschreiben, abends keine Nachrichten und kurze Bewegung vor dem Schlafen. Auch sie sagt, dass Kinder abends viel Nähe brauchen und das Zubettgehen deshalb oft in die Länge ziehen."
    },
    {
     "podcast": "gfk",
     "text": "Kathy Weber erklärt, dass in der Gewaltfreien Kommunikation zuerst die eigene Situation geklärt wird (Selbsteinfühlung): Gefühle wie erschöpft, überfordert oder genervt zeigen unerfüllte Bedürfnisse wie Schlaf, Unterstützung oder Verlässlichkeit, und das ist für sie völlig legitim. Belastende Gedanken wie „Ich bin eine schlechte Mutter“ sollen nicht verurteilt, sondern in Gefühle und Bedürfnisse übersetzt werden. Sie stellt die Bedürfnisse der Eltern an die erste Stelle, weil Kinder davon abhängen, nennt Selbstfürsorge Arbeit im Kleinen und Täglichen und sieht darin keinen Egoismus. Wie die anderen Podcasts rät sie zu Hilfe aus dem Umfeld und zum Abgeben von To-dos; ihr eigener Schwerpunkt ist aber die Eigenverantwortung: Eltern erfüllen ihre Bedürfnisse selbst, dürfen andere bitten, die auch Nein sagen dürfen, und sollen von Kindern nicht erwarten, dass sie diese Bedürfnisse wahrnehmen. Bedürfnisse müssten nicht zu hundert Prozent erfüllt sein, wichtig sei, anzufangen. Schlafmangel bezeichnet sie als Foltermethode."
    }
   ],
