    "Probiert, wenn nichts hilft, einmal einen Spielbogen aus und denkt daran, dass Babys ab etwa drei Wochen gucken wollen und überreizt sein können.",
    "Gegen Bauchweh helfen Tragen, Abhalten, Kümmel-Fenchel-Öl, Entschäumer-Tropfen und Bakterientropfen, doch sprecht das mit Hebamme oder Kinderarzt ab, denn Kümmel vertragen nicht alle Babys.",
    "Wollt ihr beim ersten Kind vorbereitet sein, bringt euch bei Babys im Umfeld ein, mit wickeln, baden, beruhigen und tragen, und zwar mit echter Verantwortung, nicht nur bei den schönen Momenten.",
    "Verplant nicht den ganzen Nachmittag und lasst Raum für das Baby; rechnet damit, dass es euren Zeitplan komplett sprengen kann.",
    "Sagt beim Wickeln und Pflegen vorher, was ihr tut, und benennt einfühlsam, was das Baby vermutlich erlebt, statt mechanisch zu hantieren."
