   "sichtweisen": [
    {
     "podcast": "mutti",
     "text": "Die Hosts reagieren beim dritten Baby nicht mehr auf jedes Meckern sofort und unterscheiden Meckern, normales Weinen und Schreien wie am Spieß. Sie rechnen damit, dafür kritisiert zu werden, und betonen, dass sie ihr Baby nicht schreien lassen. Kommentaren, Babys könnten aus Gründen der Hirnentwicklung nicht warten, widersprechen sie. Rückblickend glauben sie, ihren ersten Kindern Chancen zur Selbstregulation genommen zu haben, weil sie jedes Weinen sofort beenden wollten; dass Babys durch Erfahrung Toleranz fürs Warten lernen, nennt die Mutter ihre eigene Annahme, keine Studienlage. Die Vorstellung, Babys müssten ständig getragen werden, halten sie für eine Gegenbewegung zu früher und für übertrieben, und sie verweisen auf andere Kulturen mit verschiedenen Wegen. Zur Vorbereitung sagt ein Host zunächst, ohne Praxis gehe es kaum, eine Hostin hält es in Kulturen mit gemeinschaftlicher Betreuung für eher möglich. Ihre Erklärung, das Gehirn werde durch Schwangerschaft und Fürsorge umstrukturiert und erkenne Signale besser, ordnen sie als eigene Theorie ein. Ganz vorbereiten lasse sich niemand auf die Rund-um-die-Uhr-Verantwortung."
    },
    {
     "podcast": "artgerecht",
     "text": "Nicola Schmidt erklärt mit Verweis auf Burkeman und Sarah Lanier, Babys seien Verfechter eines tätigkeitsorientierten Lebens: Sie schlafen, essen und spielen, wenn es soweit ist und so lange es dauert. Das sprenge den Zeitplan besonders von Eltern, die ihr Leben lang zeitorientiert gelebt haben, und spontane Besuche stressten dann zusätzlich. Sie berichtet, in tätigkeitsorientierten Kulturen mache Babyschlaf weniger Probleme, nennt dafür aber keine Studie. Nichts davon sei falsch, weder Eltern noch Kind. Mit mutti stimmt sie überein, dass sich Eltern am Baby orientieren und Druck herausnehmen dürfen; mutti geht stärker auf konkrete Situationen wie Meckern, Ablegen und Schreien ein, sie auf den Umgang mit Zeit und Planung."
    },
    {
     "podcast": "gfk",
     "text": "Kathy Weber erklärt, dass die Gewaltfreie Kommunikation (GfK: Beobachtung, Gefühl, Bedürfnis, Bitte) ihrer Überzeugung nach schon mit Neugeborenen funktioniert, auch nonverbal. Studien dazu gebe es nicht, sie bejaht es aus eigener Erfahrung. Als Bedürfnisse von Säuglingen nennt sie Nahrung, Schlaf, Ausscheidung, Nähe und Vertrauen, und das Baby brauche nach dem engen, warmen, dunklen Mutterleib Geborgenheit und gedämpfte Reize. In den ersten Wochen stellt sie die Bedürfnisse des Babys zunächst vor die eigenen, betont aber, dass Eltern trotzdem für sich sorgen. Wichtiger als die Reihenfolge der vier Schritte ist ihr die Haltung, dass das Baby so okay ist, wie es ist. Sie warnt davor, das Kind totzureden, und betont, dass es kein Richtig oder Falsch gibt; wie die anderen Podcasts arbeitet sie bedürfnisorientiert."
    }
   ],
