   "kurz": "Grob lassen sich vier Erziehungsstile unterscheiden: autoritär, permissiv, autoritativ und vernachlässigend. Als richtig gilt der autoritative Mittelweg mit viel Wärme und klarer Führung. Strenge ohne Wärme wird ebenso abgelehnt wie die Idee, Kinder nicht zu erziehen; die Eltern, die das so einordnen, sahen sich früher selbst als zu permissiv.",
   "tipps": [
    "Strebt Wärme und Führung gleichzeitig an: Pflegt die Beziehung und bringt dem Kind bei, wie es im Zusammenleben läuft.",
    "Fragt euch bei einer schwierigen Phase, welche Entwicklungsaufgabe gerade ansteht, und begleitet euer Kind dabei, statt nur abzuwarten.",
    "Reagiert schon beim Baby klar, wenn es haut, zum Beispiel indem ihr es kurz auf den Boden setzt und sagt, dass es euch wehtut.",
    "Erfüllt nicht nacheinander jeden Essenswunsch, wenn das Kind nach einem Bissen etwas anderes will; Kinder brauchen Orientierung.",
    "Lebt Gewohnheiten wie Ordnung selbst mit Freude vor und etabliert sie früh.",
    "Bleibt auch bei einer Entscheidung gegen den Willen des Kindes liebevoll und klar und übertragt euren Stress nicht aufs Kind.",
    "Wenn ihr eher zu lasch seid, sucht euch Ratgeber, die euch im Nein-Sagen bestärken.",
    "Fragt euch auch, ob ihr euch selbst so behandelt, dass eure eigene Würde geachtet wird.",
    "Fragt euch immer wieder, was euer Kind für eine sichere Bindung braucht und wie ihr das mit seinem Bedürfnis nach Autonomie vereinbart."
   ],
   "sichtweisen": [
    {
     "podcast": "mutti",
     "text": "Die Hosts beschreiben permissiv als viel Wärme ohne Führung, autoritär als viele Regeln und Gehorsam ohne Wärme und autoritativ als viel Wärme plus Führung. Das Bild dafür ist ein Bergführer, der souverän vorangeht, das Kind nicht überfordert und Pausen zulässt. Sie verweisen auf eine Studie, nach der Wärme für den Erfolg von Kindern nur zusammen mit Führung zählt; Bindung allein mache Kinder nicht erfolgreicher. Sie sehen sich selbst als früher zu permissiv und vermuten, dass heutige Ausraster damit zusammenhängen, dass sie in den ersten drei Jahren zu wenig klar waren. Die Haltung, Erziehung sei an sich schlecht oder Gewalt, halten sie für schädlich, betonen aber, dass sie keine Strenge mit der Brechstange wollen. Eine Phase sei ein Hinweis auf eine Entwicklungsaufgabe und höre nicht zuverlässig von allein auf. Als Alternative zu streng bedürfnisorientierter Erziehung finden sie die Menschenwürde und Gleichwürdigkeit nach Jesper Juul überzeugend: Kinder sind gleich viel wert, auch mit anderen Fähigkeiten. Sie räumen ein, dass Tipps vom Kontext abhängen, denn wer zu hart erzieht, braucht andere Hinweise als wer zu lasch ist."
    },
    {
     "podcast": "gfk",
     "text": "Kathy Weber unterscheidet dominanzorientierte und bedürfnisorientierte Systeme: In einer bedürfnisorientierten Familie werden alle Bedürfnisse im Einklang gesehen und der Mensch wird mit seiner Würde angenommen. Verbundenheit und Autonomie ergänzen sich laut ihr: Im autoritären Stil findet keines von beiden Platz, im antiautoritären nur Autonomie, die ohne Verbundenheit nicht erfüllt werden kann. Sie grenzt sich also von beiden Extremen ab und rät, sich zu fragen, was das Kind für sichere Bindung braucht und wie das zu seinem Bedürfnis nach Autonomie passt. In einer anderen Folge erzählt ihr Vater von einer strengen Erziehung mit körperlichen Strafen, die er nicht weitergab; geblieben seien aber Schweigen und Rückzug im Streit. Sie schließt daraus, dass jede Generation Muster ein Stück weit durchbrechen kann, und rät, die eigenen Eltern nicht zu verurteilen, sondern ins Gespräch zu kommen."
    }
   ],
