   "kurz": "Eltern müssen nicht perfekt sein, Fehler gehören dazu. Die Hosts von mutti sagen, problematisch werde es erst, wenn man Fehler nicht sehen will; Nicola Schmidt rät zu einem liebevollen Alltag und zum Blick auf die Ängste hinter dem Perfektionsdrang. Kathy Weber (gfk) schlägt vor, statt sich zu entschuldigen die eigene Handlung zu bedauern und das unerfüllte Bedürfnis dahinter anzuschauen, ohne sich zu verurteilen.",
   "tipps": [
    "Erinnert euch daran, dass ein liebevoller Alltag reicht und er nicht perfekt sein muss.",
    "Versteht Erziehungstipps als Buffet: Nehmt, was zu euch passt, probiert aus und lasst weg, was nicht passt.",
    "Ändert nur das, was euch in eurer Familie wirklich stört, denn ihr seid nicht schlechtere Eltern, wenn ihr etwas anders macht.",
    "Wägt ab, was mehr schadet, zum Beispiel 20 Minuten Fernsehen oder völlig überlastete Eltern, die nicht mehr liebevoll reagieren können.",
    "Schaut ehrlich hin, was nicht funktioniert, statt es mit Temperament oder Phase wegzuerklären.",
    "Fragt euch, was euch antreibt und welche Angst dahintersteckt, und prüft ehrlich, ob das Befürchtete wirklich passiert; oft geht es den Kindern gut, auch wenn ihr mal laut seid.",
    "Entschuldigt euch bei eurem Kind mit dem Gedanken, dass das Verhalten nicht in Ordnung war, ihr selbst aber kein schlechter Mensch seid, und ändert, was euch dazu gebracht hat. Kathy Weber (gfk) empfiehlt statt der Entschuldigung ein Bedauern: Ihr sagt, was ihr getan habt und welches Bedürfnis dabei offen blieb, und betont, dass das Kind nicht schuld ist.",
    "Ruft nach einem schlechten Tag einen lieben Menschen an und erinnert euch, dass morgen ein neuer Tag mit neuen Chancen kommt und Bindung sich neu aufbauen lässt.",
    "Tauscht euch mit anderen Eltern aus, denn das Gefühl, nicht allein zu sein, entlastet enorm."
   ],
   "sichtweisen": [
    {
     "podcast": "mutti",
     "text": "Die Hosts werben für Gelassenheit und Selbstvertrauen statt Perfektionsanspruch. Sie hinterfragen das verbreitete Narrativ, dass schon Schimpfen traumatisiere und dass jedes Problem in der Kindheit liege, und merken an, dass frühere Generationen noch Gewalt erlebt haben. Ein Vorbild ist für sie nicht nur ein einzelner Elternteil, sondern die Summe der Umwelt, in der ein Kind aufwächst. Ratgeber ohne Quellen spiegeln aus ihrer Sicht die Sicht der jeweiligen Fachperson, auch ihre eigenen Tipps sehen sie nur als Anregung. Gewaltfreie Kommunikation kann nach ihrer Beobachtung auch Aggression tarnen, und ruhig zu bleiben mache nicht automatisch zu besseren Menschen. Sie gehen selbstkritisch, aber versöhnlich mit sich um: Ihren bisherigen Weg sehen sie als nötig, weil ihnen anfangs Wissen und Fähigkeiten fehlten. Besonders schwer einzugestehen seien aufopferungsvolle Fehler, bei denen man jahrelang über die eigenen Grenzen ging. Wer öffentlich einen Erziehungsstil propagiert, tue sich mit Fehlern besonders schwer. Gegenüber den eigenen Eltern haben beide keinen Groll, weil Eltern nicht alles beibringen können und jede Generation etwas verbessert."
    },
    {
     "podcast": "artgerecht",
     "text": "Nicola Schmidt sagt, viele Eltern seien erschöpft, weil sie ideale Eltern sein wollen, und verweist auf Winnicott, nach dem ausreichend gute Eltern ausreichen. Ihrer Ansicht nach wird die Kindheit durch Perfektionsdruck nicht besser, ein liebevoller Alltag genügt. Hinter dem Drang sieht sie oft Antreiber nach dem Muster, erst wenn ich so gut bin, bin ich gut genug. Sie unterscheidet Scham (ich bin schlecht) von Schuld (ich habe etwas getan, das nicht in Ordnung war) und nennt das Entschuldigen die Königsdisziplin. Sie zählt sich selbst zu den Betroffenen. Mit mutti stimmt sie überein, dass Gelassenheit und Selbstmitgefühl statt Perfektion helfen und Fehler dazugehören; sie setzt aber stärker bei den inneren Antreibern, der Scham und der Entschuldigung an, während mutti eher Ratgeber als Buffet und Abwägen betont."
    },
    {
     "podcast": "gfk",
     "text": "Kathy Weber erklärt, dass jeder Mensch in jedem Moment sein einzig Mögliches tut, auch wenn er hinterher anders reagiert hätte, als er wollte. Hinter dem Druck, perfekt zu sein, sieht sie kein echtes Bedürfnis, sondern eher den Wunsch nach Harmonie, Annahme und Wertschätzung für sich selbst. Schuldgefühle und Selbstverurteilung lähmen laut ihr; sie verzichtet bewusst auf das Wort Entschuldigung, weil es Schuld und damit ein Richtig und Falsch voraussetze. Stattdessen bedauert man in der Gewaltfreien Kommunikation (GfK): Man benennt, was geschehen ist, und welches Bedürfnis dabei unerfüllt blieb. Eltern sollen zudem zeigen, dass sie im Prozess sind, und Kinder entlasten, die sich schnell schuld fühlen, wenn Eltern überfordert sind. Anders als Nicola Schmidt, die das Entschuldigen als Königsdisziplin nennt, lehnt sie das Wort und den Schuldgedanken ab; sie räumt ein, dass vielen das schwerfällt und dass sie selbst nicht perfekt ist."
    }
   ],
