   "kurz": "Unter guten Bedingungen wie sauberem Wasser und richtiger Zubereitung ist die Flasche nicht schlecht für das Baby. Bindung hängt nicht am Stillen, und eine entlastete Mutter ist für das Kind oft besser als eine erschöpfte. Das gibt persönliche Erfahrungen wieder und ist keine fachliche Beratung.",
