   "kurz": "Fremdeln hat laut Nicola Schmidt nichts mit dem Stillen zu tun, sondern ist ein normaler Effekt, der viele Kinder ab etwa acht bis neun Monaten betrifft. Die Aussage, ein gestilltes oder eng gebundenes Kind könne sich nicht an andere binden, stimmt ihrer Ansicht nach nicht. Zwingt das Kind nicht zum Papa, und der Papa muss es nicht persönlich nehmen.",
