    "Entscheidet als Eltern bei Wünschen wie „Mama soll ins Bett bringen“ selbst, wer für welches Kind zuständig ist, und teilt es mit. Die Kinder müssen nicht zustimmen, dürfen aber ihren Wunsch äußern.",
    "Begleitet Frust und Wut mit Empathie, etwa: „Ich höre dich, du vermisst Mama, ich bin da, wir schaffen das.“ Das kann sich mehrfach wiederholen.",
