   "kurz": "Kathy Weber erklärt, dass die Gewaltfreie Kommunikation (GfK) nach Rosenberg für sie vor allem eine Haltung ist, getragen von Grundannahmen: Jeder tut in jedem Moment das Bestmögliche, um sich ein Bedürfnis zu erfüllen, und jeder ist für seine eigenen Gefühle und Bedürfnisse selbst zuständig. Das heißt nicht, alles hinzunehmen; Grenzen setzt man ohne Verurteilung. Die Formulierungen lassen sich lernen, die Haltung wächst ein Leben lang.",
   "tipps": [
    "Atmet bei Ärger kurz durch und fragt euch, welches Bedürfnis hinter dem Verhalten des anderen stecken könnte.",
    "Fragt euch zuerst, was ihr selbst für euch tun könnt, bevor ihr über den anderen urteilt.",
    "Macht nicht mit, wenn ein Kind scheinbar blockiert: Fragt, was es braucht, um mitmachen zu können, etwa mitentscheiden oder Nähe.",
    "Lasst Meinungsänderungen zu: Das Kind darf sie äußern, ob sie umgesetzt werden, ist eine zweite Frage.",
    "Ersetzt \"Das macht man nicht\" durch einen klaren Stopp, beschreibt, was ihr gesehen habt, und fragt nach Gefühl und Bedürfnis.",
    "Sagt, was ihr wollt, statt zu verbieten, etwa \"Bleib hier bei mir stehen, da bist du in Sicherheit\".",
    "Statt \"gleich\" nennt eine konkrete Zeit oder Bedingung, und statt \"aber\" probiert \"gleichzeitig\".",
    "Wenn ihr ein Nein erwägt, spiegelt erst den Wunsch des Kindes und sucht dann eine Lösung für beide Bedürfnisse.",
    "Seid nachsichtig mit euch: Üben, aus Misslungenem lernen, nicht fertigmachen."
   ],
   "sichtweisen": [
    {
     "podcast": "gfk",
     "text": "Kathy Weber nennt sechs Grundannahmen: Menschen leben gern in Gemeinschaft und tragen zum Wohl aller bei, solange ihre Bedürfnisse weitgehend erfüllt sind; andere sind nicht für die eigenen Gefühle verantwortlich; die Ursache der Gefühle sind die Bedürfnisse; jeder ist selbst für seine Bedürfnisse zuständig; alle haben dieselben Bedürfnisse; jeder tut sein Bestmögliches. Dazu gehört, dass man jederzeit die Meinung ändern darf. Die Annahme vom Bestmöglichen sei für sie die schwierigste, sie arbeite täglich damit; sie bedeute nicht, Verhalten zu akzeptieren, Grenzverletzungen dürfe man begrenzen. Sie berichtet, drei Jahre lang nur die Technik gekannt zu haben, was wie ein empathischer Roboter gewirkt habe, und sagt, es gebe keine richtige oder falsche GfK. Beim Verzicht auf Wörter wie \"man\", \"nein\", \"nicht\", \"gleich\" und \"aber\" sagt sie, jedes Wort habe seine Berechtigung, die Veränderung verlaufe aber in Phasen und verbessere spürbar die Verbindung. Regeln, Belohnung und Bestrafung lehnt sie ab; ihrer Ansicht nach sind viele Menschen deshalb wenig bereit, zum Gemeinwohl beizutragen."
    }
   ],
