   "kurz": "Nicola Schmidt entlastet Eltern: Ein Blick aufs Handy, während das Baby schläft oder mit geschlossenen Augen stillt, scheint kein Problem zu sein, und das blaue Licht stört den Babyschlaf laut ihr nicht nachweislich. Stressig für das Baby ist eher der plötzliche Kontaktabbruch, etwa wenn ihr mitten im Spielen nach einer Nachricht greift. Hilfreich ist, die Pause anzukündigen und euch danach bewusst wieder zuzuwenden.",
   "tipps": [
    "Kündigt an, was ihr tut, bevor ihr zum Handy greift, zum Beispiel: „Ich gehe jetzt kurz ans Telefon“, auch wenn das Baby die Worte noch nicht versteht.",
    "Wendet euch dem Handy dann ganz zu und erledigt, was nötig ist. Das Baby ist trotzdem irritiert, auch wenn ihr nebenbei weiter mit ihm sprecht.",
    "Wendet euch danach bewusst wieder dem Baby zu und sagt ihm, dass ihr kurz weg wart und jetzt wieder da seid. Gebt Worte dafür, was passiert ist.",
    "Macht euch keine Vorwürfe, wenn ihr das Handy beim Stillen oder bei einem schlafenden Baby nutzt. Es kommt darauf an, wie viel und welche Inhalte.",
    "Achtet besonders auf Momente, in denen ihr mitten in einer Interaktion nach dem Handy greift, etwa nach einer Push-Nachricht.",
    "Legt das Handy bei der Heimkehr an einen Ort, an dem ihr nicht danach greift, etwa in eine Schublade.",
    "Beobachtet zuerst, wann und wie ihr zum Handy greift; erst dann könnt ihr etwas ändern."
   ],
   "sichtweisen": [
    {
     "podcast": "artgerecht",
     "text": "Nicola Schmidt sagt, Studien zeigten, dass Babys nicht schlechter schlafen, wenn Eltern neben ihnen ein Smartphone nutzen. Dass das blaue Licht der entscheidende Faktor für alle Babys ist, sei nicht nachgewiesen, die Effekte seien sehr klein. Das Handy dient Eltern laut ihr auch zur Entspannung, zum Organisieren des Alltags, zur Information und zum Kontakthalten. Die Forderung, es müsse einfach weg, hält sie deshalb für schwierig. Als eigentliches Problem nennt sie den abrupten Abbruch der Interaktion: Eine aktuelle Studie, die sie erwähnt, zeige, dass das für Babys ähnlich stressig ist wie die Still-Face-Situation, in der die Bezugsperson das Baby ansieht, aber nicht reagiert. Der Stress sinke, wenn Eltern sich wieder zuwenden. Sie nennt die Studien nur allgemein und verweist für mehr auf ihre Fortbildung und die App."
    },
    {
     "podcast": "gfk",
     "text": "In einer Folge über Achtsamkeit sprechen Kathy Weber und ihr Gesprächspartner Peter Bär über die eigene Handynutzung als Eltern. Peter Bär sagt, das Handy sei so gebaut, dass es Aufmerksamkeit bindet, und es liefere kleine Dopamin-Kicks. Sind Eltern ständig daran, seien sie nicht präsent, und das Kind könne das Verhalten übernehmen. Ohne Handy fühle sich der Anfang wie Entzug an, danach nähmen beide Sinneseindrücke intensiver wahr. Beide bewerten das Handy nicht grundsätzlich als schlecht, es sei auch ihr Arbeitsgerät, und sie verstehen ihre Erfahrungen als Einladung zur Selbstbeobachtung, nicht als Regel. Das ist deutlich kritischer als die entlastende Haltung von Nicola Schmidt, und es geht um ältere Kinder, nicht um Babys. Die Folge nennt keine Studien."
    }
   ],
