   "kurz": "Das Einschlafen gelingt leichter, wenn ihr selbst entspannt seid und weniger Druck auf die Uhrzeit legt. Dauert die Begleitung länger als eine halbe Stunde, ist das Kind laut mutti schon übermüdet oder noch nicht müde; Nicola Schmidt sieht abendliches Aufdrehen meist als Übermüdung, manchmal aber auch als Hinweis, dass das Kind noch nicht müde ist oder Kontakt braucht. Ein festes Ritual ist nicht nötig.",
   "tipps": [
    "Gestaltet die Begleitung so, dass sie euch selbst guttut, etwa mit gedämpftem Licht, Lesen oder einem Hörbuch, und führt kein Ritual ein, das ihr nicht mögt. Entspannt euch zuerst selbst und verschiebt nicht eure ganze Freizeit oder den Haushalt auf die Zeit, in der das Kind schläft, sonst entsteht Druck.",
    "Lernt zu unterscheiden, ob euer Kind schon drüber oder noch nicht müde ist: Ist es drüber und zappelig, sagt bestimmt, dass es jetzt ins Bett geht, und begleitet es; ist es noch nicht müde, nehmt es entspannt zu eurer eigenen ruhigen Tätigkeit mit.",
    "Wenn ihr unsicher seid, ob euer Kind früher oder später ins Bett muss, probiert aus, es eine halbe bis eine Stunde später hinzulegen.",
    "Sorgt dafür, dass euer Kind schon früher am Tag Verbindung bekommt, und bietet abends Verbindungsspiele wie Tanzen, Kuscheln oder Lesen an. Sagt klar Stopp, wenn das Toben gefährlich wird.",
    "Zum sanften Abgewöhnen legt ihr das Kind hin, lest vor, geht kurz hinaus und bleibt in Hörweite, während es einschläft, oder lasst eine Hörgeschichte laufen.",
    "Sorgt für weniger Reize und ein Runterkommen vor dem Schlafen, und setzt Fernsehen nicht als Einschlafhilfe ein, denn es entspannt nur scheinbar.",
    "Weckt Kinder bei zu langem Mittagsschlaf am späten Nachmittag nach etwa einer halben Stunde.",
    "Bietet bei Hunger im Bett eine schlichte Banane oder ein Brot an und stellt eine Wasserflasche ans Bett; Kinder, die nochmal aufstehen, bringt ihr ohne viele Worte mit einem Kuss zurück.",
    "Soll jemand anderes das Kind ins Bett bringen, übt das tagsüber oder beim Mittagsschlaf, wenn die Person fit und das Kind nicht sehr müde ist, und zwingt das Kind nicht in Phasen, in denen es besonders an euch hängt."
   ],
   "sichtweisen": [
    {
     "podcast": "mutti",
     "text": "Die Hosts plädieren für mehr Gelassenheit beim Schlaf und grenzen sich von der Vorstellung ab, gute Eltern müssten ihr Kind pünktlich um 19 Uhr mit festem Ritual ins Bett bringen. Die Angst, das Kind könne ohne Begleitung nicht schlafen oder werde übermüdet, sehen sie als Teil des Problems. Laut ihnen schlafen Kinder nach einem reizüberfluteten Tag schlechter ein, und übermüdete Kinder schlafen nicht länger, sondern wachen früher auf. Eine Hostin hält echte Nachteulen bei Kindern für selten und vermutet eher, dass sie abends nicht runterkommen und erst einschlafen, wenn der Schlafdruck übermächtig wird. Der andere Host stimmt zu, dass es individuelle Vorlieben gibt. Nähe beim Einschlafen halten sie für kleine Kinder für sinnvoll, empfehlen aber, in einem passenden Alter ohne Druck auszuprobieren, ob das Kind allein einschlafen kann. Einer der Hosts räumt ein, früher selbst zu verkrampft gewesen zu sein und das beim älteren Kind eher hätte ausprobieren können. Uneinig sind sie sich, wie stark Temperament und wie stark das Verhalten der Eltern zählt. Bei Hunger im Bett ist einer der Hosts strenger: Extra-Essen soll keine Gewohnheit werden."
    },
    {
     "podcast": "artgerecht",
     "text": "Nicola Schmidt erklärt, ein Kind, das abends rennt, lacht oder Wutanfälle hat, sei meist übermüdet: Der Körper überspiele laut ihr die Müdigkeit mit einer Art Extra-Akku. Sie nennt drei mögliche Botschaften dahinter: noch nicht müde, übermüdet oder Bedürfnis nach Kontakt, und ein Kind, das den ganzen Tag kooperiert hat, habe abends oft keine Kooperationsenergie mehr. Sie rät, Verbindung früher am Tag zu schaffen und mit Verbindungsspielen statt Alleintoben zu antworten. Bei der Einschlafbegleitung durch eine zweite Person hält sie die starke Bindung an eine Hauptperson für normal und temperamentbedingt und rät zu Geduld statt Zwang. Mit mutti stimmt sie überein, dass Übermüdung abends oft hinter dem Aufdrehen steckt und dass Druck nicht hilft. Während mutti eher rät, überdrehte Kinder nicht weiter zu bespaßen, setzt Nicola Schmidt auf aktive Verbindung und Begleitung und sieht das Aufdrehen als Botschaft, nicht als Fehlverhalten."
    },
    {
     "podcast": "gfk",
     "text": "Kathy Weber liest Schwierigkeiten beim Zubettgehen als Ruf nach Führung und Hilfe. Ein Kind, das abends ständig zwischen Wünschen wechselt oder überdreht ist, hält sich ihrer Deutung nach nicht extra wach, sondern sitzt mit zu viel Verantwortung auf einem „zu großen Stuhl“ und kommt allein nicht zum Schlaf. Die Eltern entscheiden, was passiert und wer zuständig ist; das Kind gestaltet altersgemäß mit, wie. Sie rät zu einem festen Ablauf, den ihr gemeinsam mit dem Kind plant, und zu Begleitung beim Übergang vom Tag in die Nacht, etwa Abkaspern, Berührung oder den Tag verabschieden. Bei einem Siebenjährigen, der nur mit Elternteil im Zimmer schläft, sieht sie den Konflikt bei den Eltern: Eine Lösung muss auch für sie passen, Sicherheit kommt zuerst und das Alleinschlafen folgt. Das ähnelt mutti beim Thema Führung, setzt aber stärker auf Bedürfnisse beider Seiten; Führung heißt für sie ausdrücklich nicht Härte."
    }
   ],
