    "Fragt das Kind, warum es die Spange nicht mag, denn sie kann zum Beispiel nach dem Enger-Stellen wehtun, und sprecht über Schmerzen oder eine andere Spange mit dem Kieferorthopäden.",
    "Erklärt dem Kind regelmäßig, warum die Spange wichtig ist, fragt morgens nach und erinnert abends freundlich.",
    "Nutzt positive Verstärkung, zum Beispiel einen Filmabend oder ein Eis nach sieben Tagen am Stück.",
