    "Versucht einen Perspektivwechsel und fragt das Kind, was es als Elternteil an eurer Stelle sagen und tun würde.",
    "Setzt Konsequenzen erst zuletzt ein, nach vielen anderen Schritten, und lasst nicht jeden Tag einen Dauerkonflikt daraus werden."
