   "sichtweisen": [
    {
     "podcast": "mutti",
     "text": "Die Hosts grenzen sich von der Erklärung ab, hinter jedem Ärgern stecke ein unerfülltes Bedürfnis. Oft sei es weniger tiefgründig: Das Kind probiert aus, was passiert. Spannung und Unvorhersehbarkeit der elterlichen Reaktion wirken laut ihnen belohnend, ähnlich wie bei einem Glücksspielautomaten, und deshalb empfehlen sie, dem Verhalten die Reaktion zu entziehen. Sie räumen ein, dass das nach Behaviorismus klingt, halten dessen Mechanismen aber für real. Das Ignorieren gilt ausdrücklich nur für die Familie. Bei Gefahr oder Gewalt, auch auf dem Spielplatz oder unter Geschwistern, greift man ein; die Hosts ärgern sich über Eltern, die dabei zuschauen. Eine Reaktion auf Ärgern von dramatisch bis wütend verstärkt es, gerade bei kleinen Kindern. Den Dreieinhalbjährigen, der das Baby ärgert, sehen sie als normal und nicht als Charakterfehler. Für Kita-Fälle würden sie heute mit dem Personal klären, in welchen Situationen es passiert, und mit dem Kind Empathie und Perspektivwechsel üben. Früher hätten sie eher Reizüberflutung oder ein Bindungsbedürfnis vermutet. Sie raten außerdem, aggressive Serieninhalte wegzulassen, weil Medien das Verhalten stark beeinflussen. Beim Beispiel Paw Patrol sind sie sich nicht ganz einig, wie problematisch es ist. Sie sagen auch, dass sie selbst nicht immer gelassen sind."
    },
    {
     "podcast": "artgerecht",
     "text": "Nicola Schmidt behandelt in den Notizen vor allem Babys und Kleinkinder, die an den Haaren ziehen oder den Blumentopf ausräumen und dabei grinsen. Sie lehnt es ab, das als aggressiv oder bösartig zu deuten: Kinder seien kleine Forscher, die ausprobieren, was ihre Hand oder ihr Impuls kann, und das Grinsen deutet sie als Beschwichtigungssignal, nicht als Auslachen. Statt zu schimpfen und Verbote zu wiederholen, rät sie zu einer vorbereiteten Umgebung und dazu, das Verhalten nicht auf sich zu beziehen. Mit mutti stimmt sie überein, dass es kein Charakterfehler und keine böse Absicht ist und dass Schimpfen nichts bringt. Anders als mutti nennt sie hier ein Bedürfnis hinter dem Verhalten (Forschen, Graben) und löst es über die Umgebung, während mutti bei älteren Kindern empfiehlt, dem Verhalten die Reaktion zu entziehen und oft kein tieferes Bedürfnis sieht."
    },
    {
     "podcast": "gfk",
     "text": "Kathy Weber erklärt, dass ein Kind nie etwas tut, um euch oder andere zu ärgern oder zu schädigen, sondern um sich um ein Bedürfnis zu kümmern. Ein Bedürfnis ist dabei das, was ein Mensch braucht (zum Beispiel Mitbestimmung, Spiel und Spaß oder Nähe), und ein Verhalten ist nur der Weg, es zu bekommen. Wenn ein Kind auf ein Nein schimpft, die Zunge rausstreckt oder spuckt, will es ihrer Deutung nach zeigen, dass es das Nein richtig doof findet und gern selbst entschieden hätte. Sie rät, das Gefühl zu spiegeln, beim Nein zu bleiben, wo ihr verantwortlich seid, und euch selbst zu schützen, etwa durch Wegdrehen des Kopfes. Auch Wörter wie „Manipulation“ oder „Aufmerksamkeit holen“ hält sie für Bewertungen der Eltern. Damit steht sie im Gegensatz zu den mutti-Hosts: Diese sehen oft kein tieferes Bedürfnis und nehmen dem Verhalten die Reaktion; bei Kathy Weber steht das Verstehen vor jeder Strategie. Mit mutti teilt sie, dass Strafe und Belohnung nicht weiterhelfen, und dass ihr als Erwachsene führt, ohne euch angegriffen zu fühlen."
    }
   ],
