    "Löst Lautstärke im Supermarkt spielerisch: Lippen „zukleben“, „Mach mir alles nach“ mit geschlossenem Mund oder gemeinsam flüstern wie auf einer geheimen Mission.",
    "Bei einem kreischenden Baby könnt ihr wenig tun, außer es auszuhalten.",
    "Bei einem Vierjährigen hat ein Steinchen-Belohnungssystem fürs normale Sprechen statt Rufen gut geklappt."
