   "kurz": "Kathy Weber erklärt, dass Kinder Führung brauchen: Eltern sind die Erfahrenen und tragen die Verantwortung dafür, dass der Alltag gelingt. Sie bezeichnet das als fürsorglich eingesetzte Macht und grenzt es von autoritärer Erziehung (Machtmissbrauch) und antiautoritärer Erziehung (Verantwortung beim Kind) ab. Ihre Faustregel: Eltern entscheiden das Was, das Kind darf beim Wie mitgestalten.",
   "tipps": [
    "Entscheidet das Was und lasst das Kind das Wie mitgestalten, zum Beispiel: Wir machen drei Übungen, du wählst, welche zuerst.",
    "Macht statt einer Frage eine liebevolle Ansage und handelt, statt lange zu erklären; mit Empathie, ohne Belohnung, Strafe oder Manipulation.",
    "Beobachtet, ob euer Kind mit Entscheidungsfragen („Saft oder Wasser?“, „Spielplatz oder Tierpark?“) überfordert ist. Dann teilt einfach mit, was passiert.",
    "Schaut, welches Bedürfnis aus dem Bereich Sicherheit gerade Führung braucht, etwa Orientierung, Struktur oder Schutz.",
    "Ist das Bedürfnis nach Autonomie unerfüllt, erfüllt es gezielt und lasst das Kind in eurem Rahmen mitentscheiden.",
    "Bildet euch bei Streitthemen wie Medien, Zucker oder Medizin aus verschiedenen Quellen eine eigene Meinung und prüft sie immer wieder; so kommt ihr zu innerer Klarheit.",
    "Habt bei mehreren Kindern im Blick, welches Bedürfnis gerade Vorrang hat (etwa das hungrige Baby), und fangt das ältere Kind danach auf.",
    "Bleibt die Verantwortung bei euch, etwa bei notwendiger Medizin, und überlasst dem Kind nicht die Folgen.",
    "Konflikte dürfen sein; wichtig ist, sie nachzubereiten."
   ],
   "sichtweisen": [
    {
     "podcast": "gfk",
     "text": "Kathy Weber sieht es als Urbedürfnis von Kindern, den Erfahrenen zu folgen, und begründet das evolutionär. Elterliche Führung gehört für sie zum Oberbedürfnis Sicherheit (mit Schutz, Orientierung, Grenzen, Struktur), und sie vermisst sie auf gängigen Bedürfnislisten. Sie setzt Führung mit elterlicher Macht gleich, die man fürsorglich einsetzen und nicht verdrängen soll. Autoritäre Erziehung mit Belohnung, Strafe, Manipulation oder Ablenkung nennt sie Machtmissbrauch, antiautoritäre Erziehung lehnt sie ebenso ab, weil dort die Verantwortung beim Kind bleibt; sie spricht vom schmalen Grat dazwischen. Ihr Leitsatz: Was gemacht wird, entscheiden die Eltern, wie es gemacht wird, dürfen Kinder altersgemäß mitgestalten. Bei Kleinkindern verzichtet sie weitgehend auf Entscheidungsfragen, weil diese oft in Wut enden. Sie unterscheidet drei Autonomiephasen (etwa 1,5 bis 5 Jahre: alles allein machen; etwa 5 bis 9: selbst entscheiden wollen; ab etwa 9: eigene Erfahrungen sammeln), in denen Eltern immer weniger vorgeben. Führung ist für sie auch nötig, wenn Kinder zu mehreren sind: In Konflikten brauche es Prioritäten, und die Hierarchie sei kein Machtinstrument, sondern schaffe Sicherheit. Wer von dem Thema stark getriggert wird, hat laut ihr fast immer eigene Kindheitsthemen. Selbst bezeichnet sie ihre Erziehung als autoritär; ein Teil der Quellen wirbt für ihre Kurse."
    }
   ],
