    {
     "podcast": "mutti",
     "text": "Die Hosts richten sich klar an Väter: Hört auf zu helfen und übernehmt Verantwortung. Wer helfe, mache die Partnerin zur Verantwortlichen und sich selbst zum Helfer. Verantwortlich sein heiße aber nicht, alles selbst zu tun, man könne delegieren und bleibe trotzdem zuständig. Der männliche Host erzählt, dass er lange nur geholfen hat und sich noch im Prozess sieht. Bei ihnen habe auch eine 50-50-Aufteilung kein Gefühl von Gleichberechtigung gebracht, solange einer sich verantwortlich fühlte und der andere half. Viele Konflikte entstünden, weil Väter unbewusst Anerkennung für ihren Beitrag erwarten. Die Hosts erkennen an, dass in vielen Familien der Vater aus finanziellen Gründen Vollzeit arbeiten muss. Bei krasser Unzuverlässigkeit sprechen sie von einer echten Red Flag; bei Kleinigkeiten raten sie zu einem wohlwollenden Blick und warnen davor, alles als Ausdruck des Patriarchats zu deuten. Bei der Trennung sind sie leicht uneinig: Eine Host würde bei uneinsichtigem Partner eher dazu raten, der andere ist mit schnellen Trennungsratschlägen vorsichtig. Für die mentale Entlastung des Kopfes empfehlen sie Aufschreiben, Planung und Routinen, die als Hilfsmittel und nicht als Zwang gedacht sind."
    },
    {
     "podcast": "artgerecht",
     "text": "Nicola Schmidt spricht das Thema nicht als Väter-Appell an, sondern aus Sicht der Planung und Selbstfürsorge. Sie beschreibt, dass vor Festen bei einem Elternteil die ganze Liste rattert, während der andere improvisiert, und dass die Wut nicht aus Perfektionismus oder Lässigkeit entsteht, sondern aus fehlender gemeinsamer Strategie. Ihr eigenes Experiment, nichts vorzubereiten und nichts zu sagen, nennt sie selbst unfair. Das Fest wurde trotzdem entspannt, und die Kinder erinnerten sich nur an die Wut am Vorabend. Bei Überforderung durch Aufgaben rät sie, auf der eigenen Seite zu stehen und Prioritäten zu setzen. Sie räumt ein, dass sich nicht alles delegieren lässt. Mit den mutti-Hosts stimmt sie darin überein, dass Verantwortung ausdrücklich übergeben werden muss; anders als diese betont sie dabei, dass keiner im Paar falsch liege."
    },
    {
     "podcast": "gfk",
     "text": "Kathy Weber setzt bei Zuständigkeiten statt bei Hilfe an: Die Familie sammelt gemeinsam, welche Aufgaben anfallen, und verteilt sie als feste Ministerposten, möglichst nach Vorlieben, sodass sich jeder für seinen Bereich verantwortlich fühlt, auch wenn nicht alles perfekt läuft. Wer Unterstützung braucht, sagt das als Bedürfnis und nicht als Vorwurf, ohne zu erwarten, dass der andere sofort eine Lösung hat. Wer helfen will, aber meint, es nie recht zu machen, zieht sich laut ihr oft zurück, das sei eine Strategie und keine Gleichgültigkeit. Auch Kinder können freiwillig mitmachen, wenn das Bedürfnis dahinter benannt wird. Ist der Partner nicht bereit mitzumachen, gibt es laut ihr nicht immer eine gemeinsame Lösung, dann darf man selbst entscheiden und sich anderswo Unterstützung holen."
    }
