     "text": "Nicola Schmidt beschreibt ein typisches Bild: Das Kind schläft mittags nicht ein, wälzt sich und ist quengelig, auch gestillte Kinder nuckeln lange und stehen wieder auf. Fällt der Mittagsschlaf weg, kommt das Kind abends früh ins Bett und ist mitten in der Nacht wach. Laut ihr brauchen Kinder von etwa eineinhalb bis sechs Jahren mindestens 10 Stunden Schlaf auf 24 Stunden, die meisten mehr. Wer zwei Stunden Mittagsschlaf an den frühen Abend hängt, bekomme deshalb morgens früh wieder ein waches Kind. Die Wechsel kämen oft sprunghaft. Sie nennt die Phase „messy“, steuerbar nur durch Ausprobieren, und betont, dass weder Eltern noch Kind etwas falsch machen. Eine Studie nennt sie nicht, sie spricht von Durchschnittswerten und Beobachtung."
