   "kurz": "Hinter einer schlechten Gewohnheit steckt oft ein Bedürfnis wie Stressabbau oder Langeweile. Hilfreich ist, das Verhalten wertfrei zu beobachten, eine Alternative anzubieten und kleine Erfolge zu feiern, statt nur zu verbieten. Je früher eine Gewohnheit angegangen wird, desto leichter lässt sie sich ändern.",
