     "text": "Die Hosts beschreiben das Vorgehen aus dem Habit-Reversal-Training, das laut ihnen etwa beim Nägelkauen als eine der wirksamsten Methoden gilt: Auslöser erkennen, eine Alternative überlegen und sie so oft wie möglich einsetzen. Schon die Aussicht auf eine Belohnung setze laut ihnen Dopamin frei und könne helfen, einem Drang nicht nachzugeben. Belohnungen sehen sie hier als Hilfsmittel für ein erstes Erfolgserlebnis, nicht als Dauerlösung. Manche Kinder ärgerten oder provozierten, weil es ihnen einen Kick gibt, und glaubten irgendwann wirklich, sie könnten nicht anders; dann sei ein Erfolgserlebnis besonders wichtig. In einer Familie waren nach etwa einem halben Jahr alle Nägel lang, in einer anderen merkte ein Kind, das lange das Geschwister ärgerte, dass es den Impuls doch unterdrücken kann. Eine Host erzählt, sie habe als Erwachsene lange gebraucht, verletzende Impulse in Beziehungen zu kontrollieren."
