   "kurz": "Kathy Weber rät, das Kind nicht nur kognitiv, sondern auch emotional und sozial zu beobachten und auf den eigenen Stand statt auf äußere Erwartungen zu schauen. Dass das Kind zur Schule will, heißt für sie nicht, dass es bereit ist.",
