   "sichtweisen": [
    {
     "podcast": "mutti",
     "text": "Die Hosts sehen Selbstständigkeit und Verantwortung als zusammengehörig und als Kern der Schulvorbereitung. Sie setzen sich bewusst von Eltern ab, die Kindern alles abnehmen: Wer immer erinnert, nimmt dem Kind das eigene Mitdenken, und wer Aufräumen in Ruhe erledigt, während das Kind spielt, weist ihm die Rolle des Zuschauers zu. Ihr Bild ist der Bergführer, der Wege zeigt, statt das Kind oben abzusetzen. Sie vermuten, dass Eltern oft den Moment verpassen, in dem ein Kind etwas allein kann. Beim Abstand halten plädieren sie für deutlich mehr Freiraum und bedauern, dass Stadtkinder weniger allein unterwegs sind. Zwei- und Dreijährige brauchen laut ihnen aber noch ständige Aufmerksamkeit. Zum kurzen Alleinlassen zu Hause geben sie bewusst keine Empfehlung, da das je nach Kind und Familie verschieden sei. Ist ein älteres Kind dauerhaft so ängstlich, dass es nichts allein schafft, sehen sie psychologische Hilfe als sinnvoll an."
    },
    {
     "podcast": "artgerecht",
     "text": "Nicola Schmidt fragt, warum Kinder nicht mitdenken, und erklärt es mit fehlender Erfahrung: Erwachsene handeln automatisch, weil ihr Gehirn aus Erfahrung schnelle Gedankenketten gelernt hat, ein Kleinkind hat diese Erfahrungen noch nicht. Statt „Pass auf!“ empfiehlt sie, Prozesse und die eigenen inneren Gedanken laut zu machen und das Kind mitzunehmen, bei möglichst vielen Gelegenheiten. Mit den mutti-Hosts teilt sie, dass Kinder nicht kritisiert, sondern als noch unerfahren gesehen werden, und dass sich der Aufwand langfristig für Eltern lohnt. Die mutti-Hosts legen den Schwerpunkt auf Aufgaben, Verantwortung und Zurückhaltung der Eltern, Nicola Schmidt auf das Erklären und Vorleben von Denkschritten. Sie räumt ein, dass das nach viel Arbeit klingt, sieht es aber als Selbstfürsorge, weil es Eltern in einigen Jahren entlastet."
    },
    {
     "podcast": "gfk",
     "text": "Kathy Weber erklärt Selbstständigkeit über das Bedürfnis nach Autonomie, das Kinder von Natur aus mitbringen und das das ganze Leben begleitet. In ihrem Konzept der „lila Liebe“ gibt es drei Autonomiephasen: etwa 1,5 bis 5 Jahre selber machen, etwa 5 bis 8 Jahre selber entscheiden, ab etwa 9 Jahren selber Erfahrungen sammeln. Eltern sollen jeweils den Rahmen erweitern, in dem das Kind selbst tun oder entscheiden darf. Feste Altersvorgaben und Druck lehnt sie ab, ebenso Lob; stattdessen beschreibt sie, was das Kind getan hat. Unterstützung macht Kinder in ihrer Sicht nicht unselbstständig, und Rückschritte oder Tage mit mehr Nähe gehören dazu, dann helft ihr ohne Verweis auf frühere Erfolge. Mit mutti und artgerecht teilt sie das Ziel, schrittweise Verantwortung abzugeben. Anders als mutti, das auf Aufgaben, Erinnern nur einmal und Frust aushalten setzt, steht bei ihr das Bedürfnis hinter dem Verhalten im Mittelpunkt, und Eltern nehmen den Druck raus, dass ein Kind schon selbstständig sein müsse."
    }
   ],
