   "kurz": "Beim Süßen ist ein Mittelweg sinnvoll: kein Totalverbot, aber auch kein unbegrenzter Zugang. Entscheidend sind ein klarer Rahmen, feste Zeiten für Süßes und das eigene Vorbild der Eltern; für die Zähne zählt laut Nicola Schmidt auch, wie oft am Tag Zucker im Mund ist. Sie rät unter drei Jahren zu möglichst keinem weißen Zucker, die mutti-Hosts sehen es entspannter.",
   "tipps": [
    "Schaut zuerst auf euren eigenen Umgang mit Süßem und was ihr als Familie wollt. Kauft wenig ein, dann muss auch weniger verboten werden; wollt ihr Süßes nicht zugänglich haben, bewahrt es außer Reichweite auf, statt es zu verbieten und offen stehen zu lassen.",
    "Legt eine feste Zeit für Süßes fest, zum Beispiel ein Stück Kuchen am späten Nachmittag, und vermeidet Süßes direkt vor den Mahlzeiten. Gekaufte Süßigkeiten müssen nicht sofort gegessen werden, das übt auch Geduld.",
    "Teilt große Mengen ein, etwa nach Halloween: Das Kind sucht sich ein paar Teile für die Woche oder eines pro Tag aus.",
    "Überlegt vorher, wo eure Grenze liegt und warum, sonst gebt ihr beim Quengeln schnell nach. Zieht als Eltern an einem Strang.",
    "Haltet den Frust der Kinder aus, wenn ihr einen neuen Rahmen einführt. Nach einigen Wochen wird es leichter.",
    "Bietet Snacks an, die die Zähne nicht sofort angreifen, zum Beispiel Gurke, Möhre oder Vollkornbrot, und gebt eher Dinge, die vielleicht süß sind, aber die Zähne weniger angreifen.",
    "Setzt Kinder nicht ständig Weißbrot, Honig- oder Marmeladenbrot, Quetschies oder Müsliriegeln aus, denn laut Nicola Schmidt kommt es darauf an, wie oft am Tag der Zahnschmelz mit Zucker in Kontakt kommt.",
    "Sprecht über euch selbst, etwa dass euch etwas zu süß ist oder ihr danach müde werdet, damit Kinder sehen, dass Ablehnen möglich ist.",
    "Argumentiert nicht mit „sonst wirst du dick“, schaut lieber auf Wohlbefinden und Körpergefühl, und kommentiert Essen und Körper eures Kindes nicht."
   ],
   "sichtweisen": [
    {
     "podcast": "mutti",
     "text": "Die Hosts haben eine bewusst entspannte Haltung zu Zucker und wissen, dass das nicht viele Eltern so sehen. Alles-oder-nichts-Denken halten sie für schädlich, strikte Verbote können ihrer Meinung nach dazu führen, dass sich alles ums Süße dreht. Komplett zuckerfrei finden sie im Alltag schwer umsetzbar, weil Kinder überall Süßes angeboten bekommen. Sie sind unsicher, ob strenge Verbote später einen Rückschlag auslösen, kennen aber auch Familien mit wenig Zucker, die heute einen gesunden Umgang haben. Kleine Kinder brauchen laut ihnen einen Rahmen, weil sie mit Dingen mit Suchtcharakter noch nicht selbst regulierend umgehen können. Zwischen den Hosts gibt es eine Nuance: Eine sieht Lebensmittel im Haus als für alle da, die andere betont, dass das Timing wichtig ist. Bei einem Kind, das heimlich viel gegessen hat, würden sie nicht bestrafen, aber ehrlich sagen, dass es blöd war. Sehr große Mengen könnten auf eine Belastung hindeuten, bei Verdacht auf Essstörung raten sie zu professioneller Hilfe. Ihre Aussagen zu Gesundheit, Darmflora und Gewicht geben sie als persönliche Erfahrung wieder, sie sind dazu keine Fachleute."
    },
    {
     "podcast": "artgerecht",
     "text": "Nicola Schmidt betrachtet Zucker vor allem aus Sicht der Zahngesundheit. Laut ihr spielen Ernährung, Mundflora und Zahnschmelz eine große Rolle, und wichtig sei, wie oft am Tag die Zähne mit Zucker in Kontakt kommen. Sie rät, Kinder nicht ständig Weißbrot, Marmeladenbrot, Quetschies oder Müsliriegeln auszusetzen, und empfiehlt weißen Zucker nur in Maßen, unter drei Jahren am besten gar nicht. Das ist deutlich strenger als die entspannte Haltung der mutti-Hosts, die ein komplett zuckerfreies Leben im Alltag für schwer umsetzbar halten. Einig sind sich beide, dass es bei Zähnen große Unterschiede zwischen Kindern gibt und nicht alles am Verhalten der Eltern hängt. Studien nennt Nicola Schmidt nicht, ihre Aussagen sind Einschätzungen."
    },
    {
     "podcast": "gfk",
     "text": "Kathy Weber setzt auf elterliche Führung mit Beteiligung des Kindes: Die Eltern bestimmen, wie viel Süßes es gibt, das Kind entscheidet mit, was in die tägliche Süßigkeitenschüssel kommt und wann es sie isst. Ist die Schüssel früh leer, gibt es später nichts mehr, und das Kind wird bei der Frustration begleitet. Eine feste Regel kann sein, dass nach dem Zähneputzen nichts Süßes mehr kommt. In einer älteren Folge wirkt ihre Schwester Jennifer Weber als Gesprächspartnerin: Sie ist gegen komplette Zuckerfreiheit, hält Zucker aber für ein Riesenthema, empfiehlt Süßes klein und direkt nach dem Essen und sagt, das Verlangen sei antrainiert. Beide raten, bei Kummer nicht automatisch Essen anzubieten, sondern zu fragen, was das Kind braucht. Ein Verbot lehnen sie nicht ab; ein Plan gibt Orientierung."
    }
   ],
