    "Fragt nach Farben und Gestaltung des Zimmers erst, wenn das Kind dort angekommen ist und eine Nacht geschlafen hat; vorher überfordert die Mitbestimmung.",
    "Sammelt vorab mit dem Kind Ideen für seine Ruhe-Oase und malt dazu Bilder, ohne sie als verbindlich zu verkaufen.",
    "Bei einem Zweijährigen reicht es, es bei den Gefühlen zu begleiten, zu winken, Tschüss zu sagen und ein Bild malen zu lassen.",
