     "text": "Kathy Weber erklärt, dass Kinder bei einem Umzug kognitiv noch gar keine Vorstellung davon haben, was Umziehen heißt; ihr Nervensystem schlägt Alarm, weil alles neu ist. Hauen und Treten einer Vierjährigen deutet sie als Rückgriff auf eine alte Strategie, mit der das Kind schon früher auf unerfüllte Sicherheit aufmerksam gemacht hat. Sie nennt das ein Signal, das man ernst nehmen darf. Sie lehnt beides ab: Kinder in Watte zu packen und das Argument, man habe das früher auch überlebt. Sie weist darauf hin, dass in der vollen Umzugszeit oft Rituale und Auftanken wegfallen. Auch bei Übergängen wie Schulwechsel, Trennung der Eltern oder Urlaub rutschen Kinder laut ihr unabhängig vom Alter auf das Bedürfnis Sicherheit, und erst wenn Führung sie erfüllt, kommen sie in ihrer Entwicklung wieder an."
