     "text": "Kathy Weber geht davon aus, dass jedes Kind ein Interesse daran hat, dass es allen in der Familie gut geht. Wertschätzung folgt für sie den vier Schritten der GfK: Beobachtung ohne Bewertung, eigenes Gefühl, erfülltes Bedürfnis, Feiern oder Danken statt Bitten. Sie grenzt sie klar von Belohnung ab: Wertschätzung hat keinen Preis und erfüllt sich selbst. Eure Gefühle werden vom Kind ausgelöst, es ist aber nicht für sie verantwortlich. Sie räumt ein, dass es sich anfangs komisch anfühlt, auch nach zwölf Jahren GfK. Kinder machen es mit der Zeit nach, entschieden freiwillig und ohne Druck."
