     "text": "In der Folge zum dritten Wochenbett schildert eine Mutter, dass sie in den ersten beiden Wochenbetten im Liegen Babyblues und depressive Gefühle entwickelte und deshalb diesmal Routinen und frühes Aufstehen wählte. Nach ihrem Körpergefühl fing sie mit kleinen Phasen an; nach etwa sechs Wochen begann die Rückbildungsgymnastik, nach acht Wochen fühlte sich ihr Beckenboden wieder normal an. Sie betont, dass sie niemandem etwas vorschreiben will, und weist die Kritik zurück, frühes Aufstehen sei unfeministisch. Die Hosts vermuten, dass das deutsche Ideal des strikten Liegens kulturell sehr spezifisch ist. Wochenbettdepression hängt ihrer Einschätzung nach vor allem mit Überforderung und fehlender Unterstützung zusammen, und sie sind skeptisch gegenüber Studien ohne Quellen. In der Folge zu Erwartungen an die Elternschaft schildern sie die körperlichen Belastungen offen, betonen aber, dass nicht alles eintreten muss und es beim zweiten oder dritten Kind oft leichter wird. Sie sagen selbst, dass sie keine Ärzte sind."
