   "kurz": "Beim Wutanfall passt dem Kind etwas nicht und es kann mit der Frustration nicht umgehen; beim Meltdown ist das Nervensystem überlastet und der Anlass wirkt nur vorgeschoben. Beim Wutanfall bleibt ihr bei der Entscheidung und haltet das Gefühl mit aus, beim Meltdown helfen Ruhe, Dasein und weniger Reize. Wutanfälle sind normal, und Selbstregulation lernen Kinder laut Nicola Schmidt erst durch sehr viele Erfahrungen mit Hilfe.",
   "tipps": [
    "Bleibt beim Wutanfall ruhig und bei eurer Entscheidung. Das Kind muss die Frustration durchstehen, nachgeben beruhigt zwar schnell, bringt aber nichts bei. Sucht nicht hinter jedem Ausbruch einen Grund, manchmal ist es einfach ein schlechter Tag.",
    "Beim Meltdown hilft vor allem, da zu sein, ruhig zu bleiben und abzuwarten. Geht mit dem Kind aus einer reizvollen Umgebung heraus. Zur Einordnung fragt euch: Passt die Reaktion zum Anlass? Kann das Kind sich noch kontrollieren? Was ist vorher am Tag passiert?",
    "Bleibt im Ausbruch möglichst still und nah beim Kind, sagt höchstens „Ich bin da“ und sorgt dafür, dass alle heil bleiben. Gefühle benennen und über die Situation sprechen könnt ihr erst danach, wenn das Kind wieder erreichbar ist.",
    "Erwartet nicht, dass sich ein Kleinkind schnell selbst reguliert. Laut Nicola Schmidt braucht das Hunderte bis Tausende Erfahrungen mit Hilfe, und es genügt, wenn ihr es einmal am Tag richtig gut schafft.",
    "Bei täglichen Dauerkrisen erwischt kleine gute Momente, auch wenn sie nur 30 Sekunden dauern, und benennt sie freundlich, zum Beispiel: Danke, dass du deinen Teller weggestellt hast. Schenkt Aufmerksamkeit auch dann, wenn gerade keine Krise ist.",
    "Seht nicht jeden Wutanfall als Fehler, manchmal muss der Druck raus. Wiederholte, lauter werdende Anweisungen erhöhen nur den Druck, gebt dem Kind lieber Orientierung.",
    "Nach einem Meltdown geht auf Schadensbegrenzung: Reize runter, Ruhe, Schlaf oder ruhiges Spiel statt Ausflug. Holt Kinder möglichst rein, bevor sie kippen, und prüft, was nach der Kita hilft, etwa rausgehen, im Auto kuscheln oder Aktivitäten aufs Wochenende zu legen. Kommt es jeden Abend zum Ausbruch, prüft Schlafenszeit und Tagesbelastung und setzt bei häufigen Ausbrüchen eher bei Schlaf, Reizen und Essen an als bei der Grenze.",
    "Übt Wut-Spiele außerhalb der Krise: Wutschrei, Wutknüller aus Zeitungspapier, Wutsocken in den Eimer werfen oder ein Wutmonster aus Kissen. Das Kind darf nur mitmachen, es ist eine Erinnerung für den Ernstfall. Bei einem Streitpunkt wie den Socken helft stattdessen mit Spiel oder einem geänderten Ablauf.",
    "Verletzt sich ein Kleinkind selbst, hindert es ruhig und liebevoll daran, etwa durch In-den-Arm-Nehmen. Kathy Weber rät außerdem, Treten und Hauen nicht zu stoppen, sondern umzuleiten: Bein halten und mit der Bewegung mitgehen, beim Kopfschlagen den Kopf halten und ein Kissen unterlegen."
   ],
   "sichtweisen": [
    {
     "podcast": "mutti",
     "text": "Die Hosts widersprechen gängigen Ratgebern: Gefühle ständig zu benennen und Gründe zu liefern, halten sie für falsch, weil Eltern den Grund nicht kennen. Wut sei laut ihnen eine erlernte, subjektive Bewertung und kein verlässliches Signal für ein Bedürfnis; ihre neurologischen Erklärungen dazu sind ihre eigene Darstellung. Das Energieampel-Konzept und Me-Time sehen sie kritisch als Wut-Vermeidung. Beim Unterschied zwischen Wutanfall und Meltdown betonen sie, dass es keinen klar definierten Fachbegriff gibt: Der Wutanfall sei wie eine Welle und meist nach rund zehn Minuten vorbei, der Meltdown wie ein Tsunami, der gut 40 Minuten dauern kann. Typisch für den Meltdown seien ständig neue Gründe und danach ein völlig erschöpftes Kind. Sie grenzen sich klar von Aussagen in sozialen Medien ab, man müsse bei Meltdowns weniger Grenzen setzen. Eine Host hält die Unterscheidung bei kleinen Kindern praktisch kaum für nötig, warnt aber davor, hinter jedem Ausbruch einen Meltdown zu sehen. Gesundheitliche Zusammenhänge wie Immunsystem, Darm oder ADHS und Autismus formulieren sie ausdrücklich als möglich, nicht als sicher."
    },
    {
     "podcast": "artgerecht",
     "text": "Nicola Schmidt entlastet Eltern: Wer ruhig bleibt und trotzdem ein ausrastendes Kind hat, macht laut ihr nichts falsch, denn Nervensysteme lernen langsam. Selbstregulation ohne Aggression sollte nach ihrer Faustregel (ohne Quelle) zwischen sechs und zehn Jahren gut klappen. Wie die mutti-Hosts sieht sie nicht hinter jedem Ausbruch einen Fehler der Eltern und rät, nicht mitzugehen, wenn das Kind hochgeht; Müdigkeit, Hunger und anstrengende Kita-Tage nennt sie ähnlich wie die Hosts als Auslöser. Sie deutet manche Wutanfälle als Stressabbau, sie nennt das scherzhaft präventives Brüllen. Ihr eigener Schwerpunkt liegt auf dem Kontakt: Bekommt ein Kind vor allem in Krisen Aufmerksamkeit, lerne sein Gehirn laut ihr, dass es dort Aufmerksamkeit gibt, deshalb sollen Eltern gute Momente verstärken. Während die mutti-Hosts Gefühle-Benennen und Bedürfnissuche kritisch sehen und den Wutanfall vom Meltdown abgrenzen, unterscheidet Nicola Schmidt in den Notizen nicht zwischen beiden. Ursachen wie Geschwisterkind, Umzug oder eine mögliche Diagnose sollten nach Möglichkeit angegangen werden."
    },
    {
     "podcast": "gfk",
     "text": "Kathy Weber erklärt, dass sie lieber von Wutausbruch statt Wutanfall spricht, weil Anfall nach Krankheit klingt. Für sie ist die Wut ein Hilferuf: Das Kind kümmert sich um sich und will niemanden ärgern, hinter der Wut liegen oft andere Gefühle wie Frust, Traurigkeit oder Überforderung. Im Ausbruch selbst soll man wenig reden, nah bleiben und dafür sorgen, dass alle heil bleiben; Hauen, Treten oder Spucken werden umgeleitet statt unterbunden, und erst danach gibt es Empathie. Anders als die mutti-Hosts hält sie das Benennen von Gefühlen und Bedürfnissen für zentral (aber erst nach dem Ausbruch) und unterscheidet nicht zwischen Wutanfall und Meltdown. Mit ihnen und Nicola Schmidt teilt sie, dass man nicht nachgibt und dass Eltern ruhig bleiben sollen. Neu ist ihr Blick auf die Bedürfnisse: Wenn die dahinterliegenden Bedürfnisse im Alltag weitgehend erfüllt sind, hört die Wut laut ihr auf, und bei täglichen Ausbrüchen lohnt sich die Frage, welches Bedürfnis das Kind so zeigt. Wer als Elternteil im Ausbruch nicht mehr kann, darf sich selbst schützen, etwa mit Gehörschutz, soll aber beim Kind bleiben; Schreien zu verbieten oder das Kind wegzuschicken hält sie für Machtmissbrauch."
    }
   ],
